"""es — virtues_c."""

T = {
"virtues_051": ("¿Qué aconseja Luqman a su hijo respecto a la voz?", ["Bajar la voz: la más detestable es la del asno", "Hablar muy alto", "No hablar nunca", "Cantar al caminar"], "«Sé moderado en tu andar y baja tu voz: la más detestable de las voces es la del asno»."),
"virtues_052": ("¿Qué tres recomendaciones da Luqman a su hijo antes de hablar de la paciencia?", ["Establecer la oración, ordenar el bien, prohibir el mal", "Viajar, comerciar, escribir", "Comer poco, dormir poco, hablar poco", "Construir, plantar, cosechar"], "«Hijito mío, establece la oración, ordena el bien, prohíbe el mal y ten paciencia ante lo que te suceda»."),
"virtues_053": ("¿Qué tres cualidades atribuye el Corán a los piadosos, en la sura Al 'Imran?", ["Gastar en la holgura y en la estrechez, contener la ira, perdonar a la gente", "Ayunar, velar, callar", "Construir, plantar, dar", "Viajar, aprender, enseñar"], "«Quienes gastan en la holgura y en la estrechez, contienen la ira y perdonan a la gente: Allah ama a los que hacen el bien»."),
"virtues_054": ("¿Qué considera el Corán mejor que una limosna seguida de una ofensa?", ["Una palabra amable y un perdón", "Un don mayor", "Un silencio total", "Un juramento"], "«Una palabra amable y un perdón valen más que una limosna seguida de agravio»."),
"virtues_055": ("¿Qué dice el Corán de la limosna dada en secreto?", ["Es mejor para quien la da", "No cuenta", "Debe anunciarse", "Está prohibida"], "«Si dais limosnas públicamente, está bien; pero si las ocultáis y se las dais a los pobres, es mejor para vosotros»."),
"virtues_056": ("¿De qué prohíbe el Corán dar limosna?", ["De lo que uno mismo solo aceptaría cerrando los ojos", "De lo nuevo", "De lo que se ama", "De lo heredado"], "«Y no escojáis lo peor de ello para gastarlo, cuando vosotros mismos no lo tomaríais sino cerrando los ojos»."),
"virtues_057": ("¿Cuándo se alcanza la verdadera piedad, según la sura Al 'Imran?", ["Gastando de lo que se ama", "Gastando lo sobrante", "Gastando en público", "Guardándolo todo"], "«No alcanzaréis la piedad hasta que gastéis de aquello que amáis»."),
"virtues_058": ("¿Qué imagen emplea el Corán para el equilibrio en el gasto?", ["No tener la mano atada al cuello ni extenderla del todo", "Cerrar la puerta", "Caminar despacio", "Contar dos veces"], "«No lleves tu mano atada al cuello, ni la extiendas del todo, pues quedarías censurado y desprovisto»."),
"virtues_059": ("¿Cómo describe el Corán el gasto de «los siervos del Compasivo»?", ["Ni derrochadores ni avaros, sino en el justo medio", "Siempre generosos sin medida", "Siempre ahorradores", "Sin dar nunca"], "«Y quienes, cuando gastan, no derrochan ni escatiman, sino que se mantienen en un justo medio»."),
"virtues_060": ("¿Qué ordena el Corán antes de entrar en una casa que no es la propia?", ["Pedir permiso y saludar a sus habitantes", "Llamar tres veces y entrar", "Entrar directamente", "Llamar desde lejos"], "«No entréis en casas ajenas sin haber pedido permiso y saludado a sus habitantes»."),
"virtues_061": ("¿Qué hacer si se pide al visitante que se vaya, según la sura An-Nur?", ["Volverse: es más puro para uno", "Insistir", "Esperar en la puerta", "Entrar igualmente"], "«Y si se os dice: “Volveos”, volveos: es más puro para vosotros»."),
"virtues_062": ("¿Qué ordena el Corán cuando alguien poco fiable trae una noticia?", ["Verificarla, no sea que se perjudique a gente por ignorancia", "Difundirla enseguida", "Escribirla", "Ignorarla siempre"], "«Si un perverso os trae una noticia, verificadla, no sea que perjudiquéis a gente por ignorancia y luego os arrepintáis»."),
"virtues_063": ("¿Qué conducta, junto a la maledicencia, prohíbe la sura Al-Huyurat?", ["Espiar y sospechar en exceso", "Viajar solo", "Hablar bajo", "Escribir cartas"], "«¡Creyentes! Evitad muchas sospechas: algunas sospechas son pecado. Y no espiéis ni habléis mal unos de otros»."),
"virtues_064": ("¿Qué ordena el Corán cuando dos grupos de creyentes combaten entre sí?", ["Reconciliarlos con equidad", "Tomar partido", "Ignorarlos", "Separarlos solo por la fuerza"], "«Si dos grupos de creyentes combaten entre sí, reconciliadlos… y sed equitativos: Allah ama a los equitativos»."),
"virtues_065": ("¿Qué prohíbe expresamente el Corán, incluso hacia un pueblo al que se detesta?", ["Que el odio aparte de la justicia", "El comercio", "La palabra", "La vecindad"], "«Que el odio hacia un pueblo no os lleve a ser injustos. Sed justos: eso está más cerca de la piedad»."),
"virtues_066": ("¿Contra quién exige el Corán testimoniar con equidad, si es preciso?", ["Contra uno mismo, contra los padres y los parientes", "Solo contra los extraños", "Solo contra los ricos", "Solo contra los pobres"], "«Sed firmes en la justicia, testigos ante Allah, aunque sea contra vosotros mismos, contra vuestros padres o vuestros parientes»."),
"virtues_067": ("¿Qué ordena el Corán devolver a sus legítimos dueños?", ["Los depósitos confiados (amanat)", "Las cartas", "Las cosechas", "Los relatos"], "«Allah os ordena devolver los depósitos a sus dueños y que, cuando juzguéis entre los hombres, juzguéis con equidad»."),
"virtues_068": ("¿A qué personas enumera la aleya 4:36 para el buen trato, después de los padres?", ["Los parientes, los huérfanos, los pobres, el vecino cercano y el lejano, el compañero, el viajero y el sirviente", "Los reyes y los jefes", "Los comerciantes", "Solo los sabios"], "«Adorad a Allah y no Le asociéis nada. Sed buenos con vuestros padres, con los parientes, los huérfanos, los pobres, el vecino cercano y el vecino lejano, el compañero de viaje, el viajero y aquellos que poseen vuestras diestras»."),
"virtues_069": ("¿Qué ordena el Corán hacia un deudor en dificultad?", ["Concederle un plazo hasta la holgura", "Perseguirlo", "Doblar la deuda", "Expulsarlo"], "«Y si está en dificultad, concededle un plazo hasta un momento de holgura; pero condonar es mejor para vosotros»."),
"virtues_070": ("¿Qué ordena la aleya más larga del Corán respecto a una deuda a plazo?", ["Ponerla por escrito", "Mantenerla en secreto", "Olvidarla", "Transmitirla oralmente"], "«¡Creyentes! Cuando contraigáis una deuda por un plazo determinado, ponedla por escrito»."),
"virtues_071": ("¿Qué prohíbe el Corán respecto a los bienes ajenos?", ["Devorarlos injustamente, o usarlos para sobornar a los jueces", "Contarlos", "Venderlos", "Guardarlos"], "«No devoréis injustamente vuestros bienes unos a otros, ni los ofrezcáis a los jueces para devorar con pecado parte de los bienes de la gente»."),
"virtues_072": ("¿Qué ordena el Corán respecto a los bienes de los huérfanos?", ["Entregárselos, sin cambiar lo bueno por lo malo", "Repartirlos", "Venderlos", "Retenerlos de por vida"], "«Dad a los huérfanos sus bienes; no sustituyáis lo malo por lo bueno ni consumáis sus bienes junto con los vuestros»."),
"virtues_073": ("¿Cómo ordena el Corán medir y pesar?", ["Dar la medida completa y pesar con balanza justa", "Redondear en beneficio propio", "Pesar a ojo", "Medir dos veces"], "«Y dad la medida completa cuando midáis, y pesad con balanza justa: eso es mejor y de mejor resultado»."),
"virtues_074": ("¿Qué prohíbe seguir el Corán, por falta de conocimiento?", ["Aquello de lo que no se tiene conocimiento: el oído, la vista y el corazón responderán", "El camino más corto", "Las caravanas", "El silencio"], "«No sigas aquello de lo que no tienes conocimiento: el oído, la vista y el corazón, de todo ello se será preguntado»."),
"virtues_075": ("¿Qué imagen da el Corán del orgullo al andar?", ["No se puede hender la tierra ni alcanzar la altura de las montañas", "Se avanza más rápido", "Se cansa uno menos", "Se hace uno respetar"], "«Y no andes por la tierra con arrogancia: no podrás hender la tierra ni alcanzar la altura de las montañas»."),
"virtues_076": ("¿Qué cualidad de la palabra ordena el Corán, prometiendo que las obras serán rectificadas?", ["Una palabra justa y recta (qawl sadid)", "Una palabra breve", "Una palabra erudita", "Una palabra escrita"], "«¡Creyentes! Temed a Allah y decid una palabra justa: Él rectificará vuestras obras y os perdonará vuestros pecados»."),
"virtues_077": ("¿Qué clase de palabra se ordenó incluso ante un tirano, en el Corán?", ["Una palabra suave", "Una palabra amenazante", "Una palabra irónica", "El silencio"], "«Y habladle con palabras suaves: quizá recapacite o tema»."),
"virtues_078": ("¿De quién dice el Corán que tiene la mejor palabra?", ["De quien llama a Allah, obra el bien y dice: soy de los musulmanes", "Del poeta", "Del orador", "Del juez"], "«¿Y quién dice mejor palabra que quien llama a Allah, obra el bien y dice: ciertamente, soy de los musulmanes?»"),
"virtues_079": ("¿De qué se apartan los creyentes que triunfan, según Al-Mu'minun?", ["De lo vano (al-lagw)", "Del trabajo", "De los viajes", "De las comidas"], "«…y aquellos que se apartan de lo vano»."),
"virtues_080": ("¿Qué dos cargas guardan los creyentes que triunfan, según Al-Mu'minun?", ["Los depósitos que se les confían y sus compromisos", "El ayuno y la vigilia", "El viaje y el comercio", "La escritura y la lectura"], "«Y aquellos que cuidan los depósitos que se les confían y sus compromisos»."),
"virtues_081": ("¿Qué dice el Corán de quien perdona y reconcilia, pudiendo devolver el mal?", ["Su recompensa incumbe a Allah", "Pierde su derecho", "Es censurado", "Debe callar"], "«La retribución de una mala acción es otra mala acción igual; pero quien perdone y reconcilie, su recompensa incumbe a Allah»."),
"virtues_082": ("¿Qué argumento da el Corán para perdonar a quien nos ha agraviado?", ["«¿No amáis que Allah os perdone?»", "«Seréis compensados con dinero»", "«Os hará poderosos»", "«Os evitará un pleito»"], "«Que perdonen y disculpen. ¿No amáis que Allah os perdone? Allah es Perdonador, Misericordioso»."),
"virtues_083": ("¿Qué tres instrucciones reúne la aleya 7:199?", ["Aceptar lo que se dé de buen grado, ordenar el bien y apartarse de los ignorantes", "Combatir, huir, callar", "Comer, beber, dormir", "Contar, escribir, leer"], "«Acepta lo que se dé de buen grado, ordena el bien y apártate de los ignorantes»."),
"virtues_084": ("¿Qué actitud recomienda el Corán ante las palabras hirientes y la prueba?", ["La paciencia y la piedad: eso es de los asuntos que requieren determinación", "La réplica inmediata", "La retirada definitiva", "El silencio despectivo"], "«Oiréis muchas ofensas de quienes recibieron el Libro antes que vosotros. Pero si sois pacientes y temerosos, eso es de los asuntos que requieren determinación»."),
"virtues_085": ("¿Cómo califica el Corán la paciencia y el perdón?", ["Son de los asuntos que requieren determinación", "Son debilidad", "Son opcionales", "Son solo para los sabios"], "«Y quien tiene paciencia y perdona, ciertamente eso es de los asuntos que requieren determinación»."),
"virtues_086": ("¿Para quiénes dice el Corán que la oración no es una carga pesada?", ["Para los humildes ante Allah (al-jashi'in)", "Para los ricos", "Para los sabios", "Para los viajeros"], "«Buscad auxilio en la paciencia y la oración: ciertamente es pesada, salvo para los humildes»."),
"virtues_087": ("¿Qué recuerda el Corán sobre lo que se detesta o lo que se ama?", ["Puede que detestes algo que es un bien, y ames algo que es un mal", "Lo que amas siempre es bueno", "Lo que detestas siempre es malo", "Siempre sabes lo que es bueno"], "«Puede que detestéis algo que es un bien para vosotros, y puede que améis algo que es un mal para vosotros. Allah sabe y vosotros no sabéis»."),
"virtues_088": ("¿Qué promete el Corán a quien teme a Allah, en cuanto a salida y sustento?", ["Una salida y un sustento de donde no lo espera", "Riqueza inmediata", "Un largo viaje", "Un cargo público"], "«A quien teme a Allah, Él le da una salida y le provee de donde no lo espera»."),
"virtues_089": ("¿Qué gratitud ordena el Corán junto con la gratitud a Allah?", ["La gratitud hacia los padres", "Hacia el amo", "Hacia el vecino", "Hacia el rey"], "«Sé agradecido conmigo y con tus padres: hacia Mí es el retorno»."),
"virtues_090": ("¿Qué límite pone el Corán a la obediencia a los padres?", ["No obedecerles si ordenan asociar algo a Allah", "No obedecerles nunca", "Obedecerles en todo", "Obedecerles solo de viaje"], "«Y si ambos te esfuerzan a asociarme algo de lo que no tienes conocimiento, no les obedezcas; pero trátalos en este mundo con bondad»."),
"virtues_091": ("¿Qué súplica enseña el Corán respecto a los padres y la descendencia?", ["Agradecer el favor, obrar el bien y que la descendencia sea rectificada", "Pedir riqueza", "Pedir un largo viaje", "Pedir un cargo"], "«Señor mío, inspírame para agradecer el favor con que me has agraciado a mí y a mis padres, y para obrar el bien; y rectifica para mí mi descendencia»."),
"virtues_092": ("¿Qué piden «los siervos del Compasivo» respecto a su familia?", ["Que sea alegría de los ojos, y ser un ejemplo para los piadosos", "Que sea rica", "Que sea numerosa", "Que viaje"], "«Señor nuestro, concédenos de nuestras esposas y descendencia alegría de los ojos, y haznos ejemplo para los piadosos»."),
"virtues_093": ("¿Cómo se comportan «los siervos del Compasivo» ante lo vano?", ["Pasan de largo con dignidad", "Se detienen a escuchar", "Responden con viveza", "Lo escriben"], "«Y aquellos que no dan falso testimonio y que, cuando pasan junto a lo vano, pasan con dignidad»."),
"virtues_094": ("¿Qué ordena el Corán en una reunión cuando se pide sitio?", ["Hacer sitio: Allah os hará sitio", "Permanecer apretados", "Salir", "Callar"], "«¡Creyentes! Cuando se os diga: “Haced sitio en las reuniones”, hacedlo: Allah os hará sitio»."),
"virtues_095": ("¿Con quién ordena el Corán estar, en la sura At-Tawba?", ["Con los veraces", "Con los poderosos", "Con los ricos", "Con los viajeros"], "«¡Creyentes! Temed a Allah y estad con los veraces»."),
"virtues_096": ("¿Con quién ordena el Corán al Profeta ﷺ mantenerse con paciencia, en Al-Kahf?", ["Con quienes invocan a su Señor mañana y tarde, deseando Su faz", "Con los jefes de tribu", "Con los ricos comerciantes", "Con los poetas"], "«Mantente con paciencia junto a quienes invocan a su Señor mañana y tarde, deseando Su faz; y que tus ojos no se aparten de ellos»."),
"virtues_097": ("¿En qué ordena el Corán ayudarse mutuamente, y en qué lo prohíbe?", ["Ayudarse en la piedad y el bien, no en el pecado y la agresión", "Ayudarse en todo", "No ayudarse con nadie", "Ayudarse solo en familia"], "«Ayudaos unos a otros en la virtud y la piedad, y no os ayudéis en el pecado y la agresión»."),
"virtues_098": ("¿Qué ordena el Corán respecto al pacto concluido y los juramentos confirmados?", ["Cumplir el pacto y no romper los juramentos tras haberlos confirmado", "Renegociarlos", "Olvidarlos", "Ocultarlos"], "«Cumplid el pacto de Allah cuando lo hayáis concertado, y no rompáis los juramentos después de haberlos confirmado»."),
"virtues_099": ("Según un hadiz narrado por al-Bujari, ¿cuándo es completa la fe de un hombre?", ["Cuando ama para su hermano lo que ama para sí mismo", "Cuando ayuna todo el año", "Cuando da todos sus bienes", "Cuando viaja a La Meca"], "«Ninguno de vosotros cree de verdad hasta que ama para su hermano lo que ama para sí mismo»."),
"virtues_100": ("¿En qué casos ve el Corán bien en los conciliábulos?", ["Ordenar una limosna, una buena acción o una reconciliación entre la gente", "Tratar de negocios", "Preparar un viaje", "Contar noticias"], "«No hay bien en muchas de sus conversaciones secretas, salvo en quien ordena una limosna, algo bueno o la reconciliación entre la gente»."),
}
